 * See https://docusaurus.io/docs/i18n/crowdin#mdx
 *
 * TODO Titus suggested a clean solution based on ```mdx eval and Remark
 * See https://github.com/mdx-js/mdx/issues/701#issuecomment-947030041
 *
 * @param content
 */
export function unwrapMdxCodeBlocks(content: string): string {
  // We only support 3/4 backticks on purpose, should be good enough
  if (content.length === 0 || !content.includes('mdx-code-block')) {
    return content;
  }

  const infoString = 'mdx-code-block';
  const infoPattern = new RegExp(`^${escapeRegexp(infoString)}$`);
  let transformed = content;

  for (const fenceSize of [3, 4]) {
    const fenceMarker = '`'.repeat(fenceSize);
    const lines = transformed.split('\n');
    const rebuiltLines: string[] = [];
    let lineIndex = 0;

    while (lineIndex < lines.length) {
      const currentLine = lines[lineIndex]!;
      let matchesFencePrefix = currentLine.length >= fenceSize;
      let markerIndex = 0;
      while (matchesFencePrefix && markerIndex < fenceSize) {
        if (currentLine[markerIndex] !== '`') {
          matchesFencePrefix = false;
        }
        markerIndex += 1;
      }
      if (matchesFencePrefix && currentLine[fenceSize] === '`') {
        matchesFencePrefix = false;
      }

      if (!matchesFencePrefix) {
        rebuiltLines.push(currentLine);
        lineIndex += 1;
        continue;
