export function unwrapMdxCodeBlocks(content: string): string {
  // We only support 3/4 backticks on purpose, should be good enough
  if (content.length === 0 || !content.includes('mdx-code-block')) {
    return content;
  }

  const infoString = 'mdx-code-block';
  const infoPattern = new RegExp(`^${escapeRegexp(infoString)}$`);
  let transformed = content;

  for (const fenceSize of [3, 4]) {
    const fenceMarker = '`'.repeat(fenceSize);
    const lines = transformed.split('\n');
    const rebuiltLines: string[] = [];
    let lineIndex = 0;

    while (lineIndex < lines.length) {
      const currentLine = lines[lineIndex]!;
      let matchesFencePrefix = currentLine.length >= fenceSize;
      let markerIndex = 0;
      while (matchesFencePrefix && markerIndex < fenceSize) {
        if (currentLine[markerIndex] !== '`') {
          matchesFencePrefix = false;
        }
        markerIndex += 1;
      }
      if (matchesFencePrefix && currentLine[fenceSize] === '`') {
        matchesFencePrefix = false;
      }

      if (!matchesFencePrefix) {
        rebuiltLines.push(currentLine);
        lineIndex += 1;
        continue;
      }

      let restAfterFence = removePrefix(currentLine, fenceMarker);
      while (restAfterFence.startsWith(' ')) {
        restAfterFence = removePrefix(restAfterFence, ' ');
      }

      const parsedFence = parseCodeFence(currentLine);
      if (
        !infoPattern.test(restAfterFence) ||
        parsedFence === null ||
        parsedFence.count !== fenceSize
      ) {
        rebuiltLines.push(currentLine);
        lineIndex += 1;
        continue;
      }

      let closingIndex = lineIndex + 1;
      let foundClosing = false;
      while (closingIndex < lines.length) {
        const candidate = lines[closingIndex]!;
        if (candidate === fenceMarker) {
          foundClosing = true;
          break;
        }
        closingIndex += 1;
      }

      if (!foundClosing) {
        rebuiltLines.push(currentLine);
        lineIndex += 1;
        continue;
      }

      let childIndex = lineIndex + 1;
      while (childIndex < closingIndex) {
        rebuiltLines.push(lines[childIndex]!);
        childIndex += 1;
      }
      lineIndex = closingIndex + 1;
    }

    transformed = rebuiltLines.join('\n');
  }

  return transformed;
}

